<% content_for :canonical do %>
  <%= render "shared/canonical", href: root_url %>
<% end %>

<%= render Shared::BannerComponent.new("homepage") %>

<% provide :social_media_meta_tags do %>
  <%= render "shared/social_media_meta_tags",
             social_url: root_url %>
<% end %>

<%= render "shared/header", header: @header %>

<%= render "feeds" %>

<div class="row">
  <% if @cards.any? %>
    <div class="small-12 column <%= "large-8" if feed_processes_enabled? %>">
      <h2 class="title"><%= t("welcome.cards.title") %></h2>

      <%= render "shared/cards", cards: @cards %>
    </div>
  <% end %>

  <% if feed_processes_enabled? %>
    <div class="small-12 large-4 column">
      <%= render "processes" %>
    </div>
  <% end %>
</div>

<% if feature?("user.recommendations") && (@recommended_debates.present? || @recommended_proposals.present?) %>
  <%= render "recommended",
             recommended_debates: @recommended_debates,
             recommended_proposals: @recommended_proposals %>
<% end %>
section "Creating Admin Notifications & Templates" do
  AdminNotification.create!(
    random_locales_attributes(
      **%i[title body].index_with do |attribute|
        -> { I18n.t("seeds.admin_notifications.proposal.#{attribute}") }
      end
    ).merge(
      link: Rails.application.routes.url_helpers.proposals_url(Tenant.current_url_options),
      segment_recipient: "administrators"
    )
  ).deliver

  AdminNotification.create!(
    random_locales_attributes(
      **%i[title body].index_with do |attribute|
        -> { I18n.t("seeds.admin_notifications.help.#{attribute}") }
      end
    ).merge(link: "https://crwd.in/consul", segment_recipient: "administrators")
  ).deliver

  AdminNotification.create!(
    random_locales_attributes(
      **%i[title body].index_with do |attribute|
        -> { I18n.t("seeds.admin_notifications.map.#{attribute}") }
      end
    ).merge(segment_recipient: "administrators")
  ).deliver

  AdminNotification.create!(
    random_locales_attributes(
      **%i[title body].index_with do |attribute|
        -> { I18n.t("seeds.admin_notifications.budget.#{attribute}") }
      end
    ).merge(segment_recipient: "administrators", sent_at: nil)
  )
end
section "Creating banners" do
  Proposal.last(3).each do |proposal|
    title = Faker::Lorem.sentence(word_count: 3)
    description = Faker::Lorem.sentence(word_count: 12)
    target_url = Rails.application.routes.url_helpers.proposal_path(proposal)
    banner = Banner.new(title: title,
                        description: description,
                        target_url: target_url,
                        post_started_at: rand((1.week.ago)..(1.day.ago)),
                        post_ended_at: rand((1.day.ago)..(1.week.from_now)),
                        created_at: rand((1.week.ago)..Time.current))
    Setting.enabled_locales.map do |locale|
      Globalize.with_locale(locale) do
        banner.description = "Description for locale #{locale}"
        banner.title = "Title for locale #{locale}"
        banner.save!
      end
    end
  end
end

