    vote   = [true, false].sample
    comment = Comment.sample
    comment.vote_by(voter: voter, vote: vote)
  end

  100.times do
    voter = not_org_users.level_two_or_three_verified.sample
    proposal = Proposal.sample
    proposal.vote_by(voter: voter, vote: true)
  end
